// Motion primitives — IntersectionObserver-based, RAF-driven, no deps.
// All hooks/components run inside React via Babel.


// === useInView — fires once when 25% visible ===
function useInView(opts = {}) {
  const ref = useRef(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    if (!ref.current) return;
    const el = ref.current;
    const io = new IntersectionObserver(([e]) => {
      if (e.isIntersecting) {
        setInView(true);
        io.disconnect();
      }
    }, { threshold: opts.threshold ?? 0.18, rootMargin: opts.rootMargin ?? '0px 0px -10% 0px' });
    io.observe(el);
    return () => io.disconnect();
  }, []);
  return [ref, inView];
}

// === <Reveal> — fade-up wrapper, optional delay & distance ===
function Reveal({ children, delay = 0, y = 18, duration = 700, as = 'div', style, ...rest }) {
  const [ref, inView] = useInView();
  const Tag = as;
  return (
    <Tag
      ref={ref}
      style={{
        ...style,
        opacity: inView ? 1 : 0,
        transform: inView ? 'translate3d(0,0,0)' : `translate3d(0,${y}px,0)`,
        transition: `opacity ${duration}ms cubic-bezier(.2,.7,.2,1) ${delay}ms, transform ${duration}ms cubic-bezier(.2,.7,.2,1) ${delay}ms`,
        willChange: 'transform, opacity',
      }}
      {...rest}
    >
      {children}
    </Tag>
  );
}

// === <RevealStagger> — wrap a set of siblings, each child gets sequential delay ===
function RevealStagger({ children, step = 70, base = 0, y = 16, duration = 650, ...wrapperProps }) {
  return (
    <div {...wrapperProps}>
      {React.Children.map(children, (child, i) => (
        <Reveal delay={base + i * step} y={y} duration={duration}>{child}</Reveal>
      ))}
    </div>
  );
}

// === useCountUp — animates from 0 to target when in view, supports formatter ===
function useCountUp(target, { duration = 1400, format = (n) => Math.round(n).toLocaleString() } = {}) {
  const ref = useRef(null);
  const [val, setVal] = useState(0);
  const started = useRef(false);
  useEffect(() => {
    if (!ref.current) return;
    const el = ref.current;
    const io = new IntersectionObserver(([e]) => {
      if (e.isIntersecting && !started.current) {
        started.current = true;
        const start = performance.now();
        const tick = (now) => {
          const t = Math.min(1, (now - start) / duration);
          // easeOutCubic
          const eased = 1 - Math.pow(1 - t, 3);
          setVal(eased * target);
          if (t < 1) requestAnimationFrame(tick);
        };
        requestAnimationFrame(tick);
        io.disconnect();
      }
    }, { threshold: 0.4 });
    io.observe(el);
    return () => io.disconnect();
  }, [target, duration]);
  return [ref, format(val)];
}

// === <CountUpStat> — wraps a stat tile cleanly ===
function CountUpStat({ target, prefix = '', suffix = '', children, ...rest }) {
  const [ref, val] = useCountUp(target);
  return <span ref={ref} {...rest}>{prefix}{val}{suffix}</span>;
}

// === useMagnetic — slight pull toward cursor on a button ===
function useMagnetic(strength = 0.25, radius = 90) {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    let raf = 0;
    let tx = 0, ty = 0, x = 0, y = 0;
    const onMove = (e) => {
      const r = el.getBoundingClientRect();
      const cx = r.left + r.width / 2;
      const cy = r.top + r.height / 2;
      const dx = e.clientX - cx;
      const dy = e.clientY - cy;
      const dist = Math.hypot(dx, dy);
      if (dist < radius + Math.max(r.width, r.height) / 2) {
        tx = dx * strength;
        ty = dy * strength;
      } else {
        tx = 0; ty = 0;
      }
    };
    const onLeave = () => { tx = 0; ty = 0; };
    const loop = () => {
      x += (tx - x) * 0.18;
      y += (ty - y) * 0.18;
      el.style.transform = `translate3d(${x.toFixed(2)}px, ${y.toFixed(2)}px, 0)`;
      raf = requestAnimationFrame(loop);
    };
    window.addEventListener('mousemove', onMove);
    el.addEventListener('mouseleave', onLeave);
    raf = requestAnimationFrame(loop);
    return () => {
      window.removeEventListener('mousemove', onMove);
      el.removeEventListener('mouseleave', onLeave);
      cancelAnimationFrame(raf);
    };
  }, [strength, radius]);
  return ref;
}

// === <Magnetic> — wrap any element to make it magnetic. Pass `inner` to apply
// a counter-translate on a child (e.g. label) for a satisfying "stretch". ===
function Magnetic({ children, strength = 0.22, style, ...rest }) {
  const ref = useMagnetic(strength);
  return (
    <div ref={ref} style={{ display: 'inline-block', willChange: 'transform', ...style }} {...rest}>
      {children}
    </div>
  );
}

// === Typewriter — types content char-by-char when in view ===
function Typewriter({ lines = [], speed = 28, lineDelay = 220, startDelay = 200, onDone, style }) {
  const [ref, inView] = useInView({ threshold: 0.3 });
  const [output, setOutput] = useState(lines.map(() => ''));
  const [done, setDone] = useState(false);
  useEffect(() => {
    if (!inView) return;
    let cancelled = false;
    let timeouts = [];
    const run = async () => {
      await new Promise((r) => timeouts.push(setTimeout(r, startDelay)));
      for (let li = 0; li < lines.length; li++) {
        const line = lines[li];
        for (let ci = 0; ci <= line.length; ci++) {
          if (cancelled) return;
          await new Promise((r) => timeouts.push(setTimeout(r, speed)));
          setOutput((prev) => {
            const copy = prev.slice();
            copy[li] = line.slice(0, ci);
            return copy;
          });
        }
        await new Promise((r) => timeouts.push(setTimeout(r, lineDelay)));
      }
      if (!cancelled) {
        setDone(true);
        onDone && onDone();
      }
    };
    run();
    return () => { cancelled = true; timeouts.forEach(clearTimeout); };
  }, [inView]);
  return (
    <div ref={ref} style={style}>
      {output.map((line, i) => (
        <div key={i} style={{ minHeight: '1.4em' }}>
          {line}
          {i === output.length - 1 && !done && <span className="vm-caret">▍</span>}
        </div>
      ))}
    </div>
  );
}

// === <CursorGlow> — soft radial glow that follows mouse inside its parent ===
function CursorGlow({ color = 'rgba(255,107,26,0.18)', size = 380 }) {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const parent = el.parentElement;
    if (!parent) return;
    if (getComputedStyle(parent).position === 'static') parent.style.position = 'relative';
    let raf = 0, tx = 0, ty = 0, x = 0, y = 0, active = false;
    const onMove = (e) => {
      const r = parent.getBoundingClientRect();
      tx = e.clientX - r.left;
      ty = e.clientY - r.top;
      active = true;
      el.style.opacity = '1';
    };
    const onLeave = () => {
      active = false;
      el.style.opacity = '0';
    };
    const loop = () => {
      x += (tx - x) * 0.12;
      y += (ty - y) * 0.12;
      el.style.transform = `translate3d(${x - size/2}px, ${y - size/2}px, 0)`;
      raf = requestAnimationFrame(loop);
    };
    parent.addEventListener('mousemove', onMove);
    parent.addEventListener('mouseleave', onLeave);
    raf = requestAnimationFrame(loop);
    return () => {
      parent.removeEventListener('mousemove', onMove);
      parent.removeEventListener('mouseleave', onLeave);
      cancelAnimationFrame(raf);
    };
  }, [size]);
  return (
    <div
      ref={ref}
      aria-hidden
      style={{
        position: 'absolute',
        top: 0, left: 0,
        width: size, height: size,
        borderRadius: '50%',
        background: `radial-gradient(circle, ${color} 0%, transparent 60%)`,
        pointerEvents: 'none',
        opacity: 0,
        transition: 'opacity 320ms ease',
        zIndex: 0,
        filter: 'blur(8px)',
      }}
    />
  );
}

// === <Tilt> — subtle 3D tilt on hover ===
function Tilt({ children, max = 6, style, ...rest }) {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    let raf = 0, tx = 0, ty = 0, x = 0, y = 0;
    const onMove = (e) => {
      const r = el.getBoundingClientRect();
      const px = (e.clientX - r.left) / r.width - 0.5;
      const py = (e.clientY - r.top) / r.height - 0.5;
      tx = py * -max;
      ty = px * max;
    };
    const onLeave = () => { tx = 0; ty = 0; };
    const loop = () => {
      x += (tx - x) * 0.12;
      y += (ty - y) * 0.12;
      el.style.transform = `perspective(900px) rotateX(${x.toFixed(2)}deg) rotateY(${y.toFixed(2)}deg)`;
      raf = requestAnimationFrame(loop);
    };
    el.addEventListener('mousemove', onMove);
    el.addEventListener('mouseleave', onLeave);
    raf = requestAnimationFrame(loop);
    return () => {
      el.removeEventListener('mousemove', onMove);
      el.removeEventListener('mouseleave', onLeave);
      cancelAnimationFrame(raf);
    };
  }, [max]);
  return (
    <div ref={ref} style={{ transformStyle: 'preserve-3d', willChange: 'transform', ...style }} {...rest}>
      {children}
    </div>
  );
}

// === <Marquee> — seamless infinite scroll ===
function Marquee({ children, speed = 40, gap = 48, style, ...rest }) {
  return (
    <div style={{ overflow: 'hidden', position: 'relative', ...style }} {...rest}>
      <div className="vm-marquee-track" style={{ display: 'flex', gap, animation: `vm-marquee ${speed}s linear infinite`, width: 'max-content' }}>
        {children}
        {children}
      </div>
    </div>
  );
}

