function HTrust() {
  const c = VM_CONTENT;
  const stats = [c.trustStat1, c.trustStat2, c.trustStat3, c.trustStat4];

  // Parse "5,000+" → { num: 5000, prefix: '', suffix: '+', countable: true }
  const parseStat = (str) => {
    const m = String(str).match(/^([^\d]*)(\d[\d,]*)(.*)$/);
    if (!m) return { countable: false, raw: str };
    const num = parseInt(m[2].replace(/,/g, ''), 10);
    return { countable: !isNaN(num), num, prefix: m[1], suffix: m[3], raw: str };
  };

  return (
    <section style={{
      borderTop: `1px solid ${H.rule}`,
      borderBottom: `1px solid ${H.rule}`,
      padding: '32px 56px',
      display: 'grid',
      gridTemplateColumns: 'repeat(4, 1fr)',
      gap: 24,
      background: H.bg,
    }}>
      {stats.map((s, i) => {
        const parsed = parseStat(s.num);
        return (
          <Reveal key={i} delay={i * 80} y={14}>
            <div style={{ borderLeft: i === 0 ? 'none' : `1px solid ${H.rule}`, paddingLeft: i === 0 ? 0 : 24 }}>
              <div style={{ ...hStyles.display, fontSize: 38, color: H.ink }}>
                {parsed.countable ? (
                  <CountUpStat target={parsed.num} prefix={parsed.prefix} suffix={parsed.suffix} />
                ) : (
                  s.num
                )}
                {i === 0 && <span style={{ color: H.orange }}>.</span>}
              </div>
              <div style={{ fontSize: 13, color: H.muted, marginTop: 4 }}>{s.label}</div>
            </div>
          </Reveal>
        );
      })}
    </section>
  );
}

