// Source: vibemakerz/src/components/home/WhatIsVibecodingSection.tsx (StudentVisual)
// Auto-cycling Learning Loop — Idea → Prototype → Improve.
// Replicates the official interaction: 3.2s auto-advance, pauses on hover,
// click a step to jump (re-pauses for 6s), respects prefers-reduced-motion.
function HLearningLoop() {
  const [activeStep, setActiveStep] = React.useState(1);
  const [isPaused, setIsPaused] = React.useState(false);
  const [reduceMotion, setReduceMotion] = React.useState(false);

  React.useEffect(() => {
    if (typeof window === 'undefined' || !window.matchMedia) return;
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReduceMotion(mq.matches);
    update();
    if (mq.addEventListener) mq.addEventListener('change', update);
    return () => { if (mq.removeEventListener) mq.removeEventListener('change', update); };
  }, []);

  const steps = [
    {
      id: 'idea',
      title: 'Idea',
      subtitle: 'Identify a problem.',
      body: (
        <div style={{
          background: H.bgWarm, border: `1px solid ${H.rule}`, borderRadius: 8,
          padding: 14, fontSize: 13, color: H.ink2, fontStyle: 'italic', lineHeight: 1.4,
        }}>
          "Make a study planner that reminds me what to revise today…"
        </div>
      ),
    },
    {
      id: 'prototype',
      title: 'Prototype',
      subtitle: 'Prompt → prototype.',
      body: (
        <div style={{
          background: H.ink, borderRadius: 8, padding: 14,
          fontFamily: '"JetBrains Mono", monospace', fontSize: 11.5, lineHeight: 1.6,
        }}>
          <div style={{ color: '#7fda8c' }}>&gt; Generating UI elements…</div>
          <div style={{ color: '#fff', marginTop: 4 }}>&gt; First version: good enough to demo</div>
        </div>
      ),
    },
    {
      id: 'improve',
      title: 'Improve',
      subtitle: 'Iterate based on feedback.',
      body: (
        <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
          <div style={{
            background: `${H.orange}15`, border: `1px solid ${H.orange}40`,
            borderRadius: 12, padding: '10px 14px', textAlign: 'center', minWidth: 80,
          }}>
            <div style={{ fontSize: 9, color: H.muted, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Today</div>
            <div style={{ ...hStyles.display, fontSize: 30, color: H.orange, fontWeight: 700, lineHeight: 1 }}>42</div>
            <div style={{ fontSize: 9, color: H.muted, marginTop: 2 }}>days to exam</div>
          </div>
          <div style={{ fontSize: 13, color: H.ink2 }}>Iterate based on feedback.</div>
        </div>
      ),
    },
  ];

  React.useEffect(() => {
    if (reduceMotion || isPaused) return;
    const interval = setInterval(() => {
      setActiveStep((prev) => (prev + 1) % steps.length);
    }, 3200);
    return () => clearInterval(interval);
  }, [isPaused, reduceMotion, steps.length]);

  const handleStepClick = (index) => {
    setActiveStep(index);
    setIsPaused(true);
    setTimeout(() => setIsPaused(false), 6000);
  };

  const getStatus = (index) => {
    if (index < activeStep) return 'done';
    if (index === activeStep) return 'now';
    return 'next';
  };

  const statusLabel = { done: 'DONE', now: 'NOW', next: 'NEXT' };

  return (
    <div
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
      style={{
        borderRadius: 16, border: `1.5px solid ${H.ink}`, background: H.bg, overflow: 'hidden',
        boxShadow: `4px 4px 0 ${H.ink}`,
      }}
    >
      <div style={{
        padding: '14px 20px', borderBottom: `1px solid ${H.rule}`, background: H.bgWarm,
        display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap',
      }}>
        <span style={{
          ...hStyles.mono, fontSize: 10, fontWeight: 700, color: H.orangeDeep,
          background: `${H.orange}15`, padding: '4px 9px', borderRadius: 999, letterSpacing: '0.05em',
        }}>LEARNING LOOP</span>
        <span style={{ fontSize: 11, color: H.muted, fontFamily: '"JetBrains Mono", monospace', letterSpacing: '0.05em' }}>
          FROM IDEA → PROTOTYPE → IMPROVEMENT
        </span>
      </div>

      <div style={{ padding: 24 }}>
        {steps.map((step, i) => {
          const status = getStatus(i);
          const isLast = i === steps.length - 1;
          const isNow = status === 'now';
          return (
            <div
              key={step.id}
              onClick={() => handleStepClick(i)}
              style={{ display: 'flex', gap: 14, cursor: 'pointer' }}
            >
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', minWidth: 30 }}>
                <div style={{
                  width: 30, height: 30, borderRadius: '50%',
                  background: status === 'done' ? H.orange : H.bg,
                  color: '#fff',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: 14, fontWeight: 700,
                  border: isNow
                    ? `2.5px solid ${H.orange}`
                    : `2px solid ${status === 'done' ? H.ink : H.rule}`,
                  transform: isNow ? 'scale(1.08)' : 'scale(1)',
                  transition: 'transform 280ms cubic-bezier(.2,.7,.2,1), background 280ms ease, border-color 280ms ease',
                }}>
                  {status === 'done' && '✓'}
                  {isNow && (
                    <div className={reduceMotion ? '' : 'vm-pulse'} style={{
                      width: 10, height: 10, borderRadius: '50%', background: H.orange,
                    }} />
                  )}
                </div>
                {!isLast && (
                  <div style={{
                    width: 2, flex: 1,
                    background: i < activeStep ? `${H.orange}AA` : H.rule,
                    minHeight: 56, marginTop: 4,
                    transition: 'background 320ms ease',
                  }} />
                )}
              </div>

              <div style={{ flex: 1, paddingBottom: isLast ? 0 : 22 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 8, marginBottom: 4 }}>
                  <h5 style={{
                    ...hStyles.display, fontSize: 16, margin: 0, fontWeight: 600,
                    color: isNow ? H.ink : H.muted,
                    transition: 'color 280ms ease',
                  }}>{step.title}</h5>
                  <span style={{
                    fontFamily: '"JetBrains Mono", monospace',
                    fontSize: 9, padding: '3px 8px', borderRadius: 999, fontWeight: 700,
                    background: status === 'next' ? `${H.muted}22` : `${H.orange}15`,
                    color: status === 'next' ? H.muted : H.orangeDeep,
                    letterSpacing: '0.06em',
                    transition: 'all 280ms ease',
                  }}>{statusLabel[status]}</span>
                </div>
                {step.id !== 'improve' && (
                  <p style={{ fontSize: 13, color: H.muted, margin: '0 0 8px' }}>{step.subtitle}</p>
                )}
                <div style={{
                  maxHeight: isNow ? 200 : 0,
                  opacity: isNow ? 1 : 0,
                  overflow: 'hidden',
                  marginTop: isNow ? 6 : 0,
                  transition: 'max-height 360ms cubic-bezier(.2,.7,.2,1), opacity 260ms ease, margin-top 260ms ease',
                }}>
                  {step.body}
                </div>
              </div>
            </div>
          );
        })}
      </div>

      <div style={{ padding: '0 24px 14px' }}>
        <p style={{ fontSize: 11, color: H.muted, textAlign: 'center', margin: 0, fontStyle: 'italic' }}>
          Click a step · hover to pause
        </p>
      </div>
    </div>
  );
}

